<?php declare(strict_types=1); $record=$detail ?? []; $version=$record['version'] ?? null; $recordId=$record[$ids[$page]] ?? null; ?>
<section id="record-detail" class="panel detail-panel" aria-labelledby="detail-title"><div class="panel-heading"><div><span class="eyebrow">RECORD DETAILS</span><h2 id="detail-title"><?= e($page==='categories'?($record?'Edit category':'Create a category'):($page==='providers'?($record['business_name'] ?? 'Provider'):'Review '.rtrim($page,'s'))) ?></h2><?php if($recordId): ?><p class="record-id"><?= e($recordId) ?></p><?php endif; ?></div><a class="text-link" href="<?= e(url($page)) ?>">Close details ×</a></div><div class="detail-content">
<?php if($page==='users'): ?>
    <div class="detail-grid"><div><h3>Account information</h3><dl class="detail-list"><?php viewPair('Full name',$record['full_name']);viewPair('Email',$record['email']);viewPair('Phone',$record['phone']);viewPair('Role',ucfirst($record['role']));viewPair('Email verified',$record['email_verified']?'Yes':'No');viewPair('Joined',localDate($record['created_at']));viewPair('Last login',localDate($record['last_login_at'])); ?></dl></div><div><h3>Account access</h3><p class="section-note">Current status: <?= badge($record['is_active']?'Active':'Suspended') ?></p><?php if($record['role']==='admin'): ?><div class="info-card">Administrator access cannot be suspended from this screen.</div><?php else: ?><form class="stack-form" method="post" action="<?= e(url('users')) ?>" <?= $record['is_active']?'data-confirm="Suspend this account? The user will lose access to the application."':'' ?>><?= viewFields('user_status',$recordId,$version) ?><input type="hidden" name="active" value="<?= $record['is_active']?'false':'true' ?>"><?php viewReason('account-reason'); ?><button class="button <?= $record['is_active']?'button-danger':'button-primary' ?>"><?= $record['is_active']?'Suspend account':'Reactivate account' ?></button></form><?php endif; ?></div></div>
    <h3 class="section-divider">Account action history</h3><?php if(empty($record['actions'])): ?><p class="muted">No account status changes have been recorded.</p><?php else: ?><ol class="timeline"><?php foreach($record['actions'] as $entry): ?><li><strong><?= e($entry['action_type']) ?></strong><time><?= e(localDate($entry['created_at'])) ?></time><p><?= e($entry['reason']) ?></p></li><?php endforeach; ?></ol><?php endif; ?>
<?php elseif($page==='providers'): ?>
    <div class="detail-grid"><div><h3>Business profile</h3><dl class="detail-list"><?php viewPair('Owner',$record['full_name']);viewPair('Email',$record['email']);viewPair('Business licence',$record['business_license']);viewPair('Location',trim(($record['city'] ?? '').', '.($record['region'] ?? ''),', '));viewPair('Experience',($record['years_experience'] ?? 0).' years');viewPair('Service radius',($record['service_radius_km'] ?? 0).' km');viewPair('Customer rating',($record['overall_rating'] ?? 0).' / 5 · '.($record['total_reviews'] ?? 0).' reviews'); ?></dl><p class="preserve-text muted"><?= e($record['bio'] ?? '') ?></p></div><div><h3>Verification decision</h3><p class="section-note">Current status: <?= badge($record['verification_status']) ?></p><?php if(!empty($record['rejection_reason'])): ?><div class="notice notice-warning"><?= e($record['rejection_reason']) ?></div><?php endif; ?><form method="post" action="<?= e(url('providers')) ?>" class="stack-form"><?= viewFields('provider_verify',$recordId,$version) ?><div><label for="provider-status">Decision</label><select name="status" id="provider-status" required><option value="">Choose a decision</option><option value="Verified">Approve provider</option><option value="Rejected">Reject application</option><option value="Pending">Return to pending review</option></select></div><?php viewReason('provider-reason','Review notes / reason'); ?><p class="field-note">Approval requires business licence information or a verified, current credential. Manually review the supporting evidence before approving.</p><button class="button button-primary">Save verification decision</button></form></div></div>
    <h3 class="section-divider">Credentials & certifications</h3><?php if(empty($record['certifications'])): ?><div class="inline-empty">No credentials have been submitted by this provider.</div><?php else: ?><div class="credential-grid"><?php foreach($record['certifications'] as $certificate): $expired=!empty($certificate['expiry_date']) && $certificate['expiry_date']<date('Y-m-d'); ?><article class="credential-card"><div class="credential-heading"><?= viewIcon('shield') ?><h4><?= e($certificate['certification_name']) ?></h4><?= badge($expired?'Expired':($certificate['is_verified']?'Verified':'Unverified')) ?></div><dl class="detail-list"><?php viewPair('Issuer',$certificate['issuer']);viewPair('Expires',$certificate['expiry_date']?localDate($certificate['expiry_date'],'d M Y'):'No expiry supplied'); ?></dl><?php if(!empty($certificate['file_url'])): ?><a class="text-link" href="<?= e(url('document',['id'=>$certificate['certification_id']])) ?>" target="_blank" rel="noopener noreferrer">Open credential document ↗</a><?php else: ?><span class="muted">No document supplied</span><?php endif; ?><?php if($certificate['is_verified'] || (!$expired && !empty($certificate['file_url']))): ?><form method="post" action="<?= e(url('providers')) ?>" class="stack-form credential-form"><?= viewFields('certificate_verify',$certificate['certification_id'],$certificate['version']) ?><input type="hidden" name="verified" value="<?= $certificate['is_verified']?'false':'true' ?>"><?php viewReason('cert-reason-'.$certificate['certification_id'],'Document review notes'); ?><button class="button button-secondary button-small"><?= $certificate['is_verified']?'Remove verification':'Verify credential' ?></button></form><?php else: ?><p class="field-note">A current credential document is required before verification.</p><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
    <div class="detail-grid section-divider"><div><h3>Working hours</h3><?php if(empty($record['hours'])): ?><p class="muted">Working hours have not been supplied.</p><?php else: ?><dl class="detail-list"><?php $days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];foreach($record['hours'] as $hour): viewPair($days[(int)$hour['day_of_week']] ?? 'Day '.$hour['day_of_week'],$hour['is_active']?substr((string)$hour['start_time'],0,5).'–'.substr((string)$hour['end_time'],0,5):'Closed');endforeach; ?></dl><?php endif; ?></div><div><h3>Portfolio</h3><?php if(empty($record['portfolio'])): ?><p class="muted">No portfolio items supplied.</p><?php else: ?><?php foreach($record['portfolio'] as $portfolio): ?><article class="portfolio-item"><strong><?= e($portfolio['title']) ?></strong><p><?= e($portfolio['description']) ?></p><?php viewSafeLink($portfolio['image_url'],'View portfolio image'); ?></article><?php endforeach; ?><?php endif; ?></div></div>
<?php elseif($page==='categories'): ?>
    <form method="post" action="<?= e(url('categories')) ?>" class="category-form" enctype="multipart/form-data"><?= viewFields('category_save',$recordId,$version) ?><div class="form-grid"><div><label for="category-name">Category name <span class="required">*</span></label><input id="category-name" name="name" required minlength="2" maxlength="100" value="<?= e($record['category_name'] ?? '') ?>" placeholder="e.g. Air-conditioning"></div><div><label for="category-parent">Parent category</label><select id="category-parent" name="parent_id"><option value="">None · top-level category</option><?php foreach(($categoryChoices ?? []) as $choice): if(($choice['category_id'] ?? '')===$recordId) continue; ?><option value="<?= e($choice['category_id']) ?>" <?= ($record['parent_category_id'] ?? '')===$choice['category_id']?'selected':'' ?>><?= e($choice['category_name']) ?><?= !$choice['is_active']?' (inactive)':'' ?></option><?php endforeach; ?></select><p class="field-note">Choose a parent to create a subcategory.</p></div><div class="span-two"><label for="category-description">Description</label><textarea id="category-description" name="description" rows="3" maxlength="500" placeholder="Describe the services customers can find in this category."><?= e($record['description'] ?? '') ?></textarea></div><div><label for="category-status">Status</label><select id="category-status" name="active"><option value="true" <?= ($record['is_active'] ?? true)?'selected':'' ?>>Active</option><option value="false" <?= !($record['is_active'] ?? true)?'selected':'' ?>>Inactive</option></select></div><div><label for="category-order">Display order</label><input type="number" id="category-order" name="display_order" value="<?= e($record['display_order'] ?? 0) ?>" min="0" max="9999" step="1" required><p class="field-note">Lower numbers appear first.</p></div><div><label for="category-color">Category colour</label><input type="color" id="category-color" name="color" value="<?= e(preg_match('/^#[0-9A-Fa-f]{6}$/',(string)($record['color_code'] ?? ''))?$record['color_code']:'#ea580c') ?>"></div><div><label for="category-icon">Category icon</label><input type="file" id="category-icon" name="icon_file" accept="image/png,image/jpeg,image/webp"><p class="field-note">PNG, JPEG or WebP. Leave empty to keep the current icon.</p><?php if(!empty($record['icon_url'])): viewSafeLink($record['icon_url'],'View current icon'); endif; ?></div></div><div class="form-actions"><button class="button button-primary"><?= $record?'Save category':'Create category' ?></button><a class="button button-secondary" href="<?= e(url('categories')) ?>">Cancel</a></div></form>
    <?php if($record): ?><div class="danger-zone"><div><h3>Delete category</h3><p>Categories with services or subcategories must be deactivated to preserve history.</p></div><form method="post" action="<?= e(url('categories')) ?>" data-confirm="Delete this category permanently? Categories that are in use cannot be deleted."><?= viewFields('category_delete',$recordId,$version) ?><button class="button button-danger">Delete category</button></form></div><?php endif; ?>
<?php elseif($page==='bookings'): ?>
    <div class="booking-summary"><div><?= badge($record['booking_status']) ?><h3><?= e($record['service_name']) ?></h3><p><?= e($record['customer_name']) ?> <span class="muted">with</span> <?= e($record['provider_name']) ?></p></div><div class="booking-amount"><span>Total amount</span><strong><?= e(money($record['total_amount'])) ?></strong></div></div>
    <div class="detail-grid"><div><h3>Service details</h3><dl class="detail-list"><?php viewPair('Scheduled',localDate($record['scheduled_datetime']));viewPair('Address',$record['customer_address']);viewPair('Urgency',$record['urgency']);viewPair('Created',localDate($record['created_at']));viewPair('Instructions',$record['special_instructions']); if(!empty($record['cancellation_reason'])) viewPair('Cancellation reason',$record['cancellation_reason']); ?></dl></div><div><h3>Administrative status update</h3><?php $transitions=['Pending'=>['Confirmed','Cancelled'],'Confirmed'=>['In-Progress','Cancelled'],'In-Progress'=>['Completed','Cancelled']]; $next=$transitions[$record['booking_status']] ?? []; if($next): ?><form class="stack-form" method="post" action="<?= e(url('bookings')) ?>"><?= viewFields('booking_status',$recordId,$version) ?><div><label for="booking-status">Next status</label><select name="status" id="booking-status" required><option value="">Choose next status</option><?php foreach($next as $status): ?><option value="<?= e($status) ?>"><?= e($status) ?></option><?php endforeach; ?></select></div><?php viewReason('booking-reason'); ?><p class="field-note">Confirming requires a successful payment. Status changes are recorded and both parties receive an in-app notification. Changing status does not issue a refund.</p><button class="button button-primary">Update booking</button></form><?php else: ?><div class="info-card">This booking is <?= e(strtolower($record['booking_status'])) ?> and has no further status transitions. Use dispute handling to review any outstanding issue.</div><?php endif; ?></div></div>
    <div class="detail-grid section-divider"><div><h3>Payment record</h3><?php $payment=$record['payment'] ?? null; if($payment): ?><dl class="detail-list"><?php viewPair('Payment status',$payment['payment_status']);viewPair('Amount',money($payment['payment_amount']));viewPair('Payment method',$payment['payment_method']);viewPair('Gateway reference',$payment['fpx_transaction_ref']);viewPair('Paid at',localDate($payment['payment_timestamp']));viewPair('Escrow recorded',$payment['escrow_held']?'Held':'Not held'); ?></dl><?php viewSafeLink($payment['receipt_url'],'View receipt'); ?><p class="field-note">The escrow field reflects the stored record. It does not independently verify funds held by a gateway.</p><?php else: ?><p class="muted">No payment has been recorded for this booking.</p><?php endif; ?></div><div><h3>Request a refund</h3><?php if(($admin['role_level'] ?? '')!=='super_admin'): ?><div class="info-card">Only a Super Admin can request refunds.</div><?php elseif(!$payment || $payment['payment_status']!=='Success'): ?><div class="info-card">A successful payment is required to request a refund.</div><?php elseif(empty($payment['version'])): ?><div class="notice notice-warning">Reload this booking before requesting a refund.</div><?php else: ?><form method="post" action="<?= e(url('bookings')) ?>" class="stack-form" data-confirm="Record this refund request? It will remain pending until the payment gateway processes it."><?= viewFields('refund_request',$payment['payment_id'],$payment['version']) ?><div><label for="refund-amount">Refund amount (MYR)</label><input type="number" id="refund-amount" name="amount" min="0.01" max="<?= e($payment['payment_amount']) ?>" step="0.01" required value="<?= e($payment['payment_amount']) ?>"></div><?php viewReason('refund-reason'); ?><p class="field-note">This records a request. No funds are moved or marked refunded by this action.</p><button class="button button-secondary">Record refund request</button></form><?php endif; ?></div></div>
    <div class="detail-grid section-divider"><div><h3>Booking history</h3><?php if(empty($record['history'])): ?><p class="muted">No status changes recorded.</p><?php else: ?><ol class="timeline"><?php foreach($record['history'] as $entry): ?><li><strong><?= e($entry['previous_status'] ?? 'Created') ?> → <?= e($entry['new_status']) ?></strong><time><?= e(localDate($entry['created_at'])) ?></time><p><?= e($entry['notes'] ?? '') ?></p></li><?php endforeach; ?></ol><?php endif; ?></div><div><h3>Dispute handling</h3><?php $openDispute=false; foreach(($record['disputes'] ?? []) as $dispute): if(in_array($dispute['status'],['Open','Under Review'],true)) $openDispute=true; ?><div class="dispute-summary"><a class="text-link" href="<?= e(url('disputes',['id'=>$dispute['dispute_id']])) ?>"><?= e($dispute['subject']) ?></a><?= badge($dispute['status']) ?></div><?php endforeach; ?><?php if(!$openDispute): ?><form class="stack-form" method="post" action="<?= e(url('bookings')) ?>"><?= viewFields('dispute_open',$recordId,$version) ?><div><label for="dispute-subject">Issue title</label><input id="dispute-subject" name="subject" minlength="3" maxlength="150" required placeholder="Briefly describe the issue"></div><?php viewReason('dispute-description','Issue details'); ?><button class="button button-secondary">Open dispute</button></form><?php else: ?><p class="field-note">An open dispute already exists. Review it before creating another.</p><?php endif; ?></div></div>
<?php elseif($page==='reviews'): ?>
    <div class="detail-grid"><div><h3>Customer feedback</h3><span class="rating-stars rating-large">★ <?= e($record['rating_score']) ?> <span>/ 5</span></span><blockquote class="review-quote"><?= e($record['review_comment'] ?? 'No written feedback supplied.') ?></blockquote><dl class="detail-list"><?php viewPair('Submitted',localDate($record['created_at']));viewPair('Verified booking',$record['is_verified_booking']?'Yes':'No');viewPair('Moderation',$record['moderation_status']);viewPair('Flagged',$record['is_flagged']?'Yes':'No');viewPair('Flag reason',$record['flag_reason']);if(!empty($record['moderation_reason'])) viewPair('Previous decision reason',$record['moderation_reason']); ?></dl><a class="text-link" href="<?= e(url('bookings',['id'=>$record['booking_id']])) ?>">View linked booking →</a><?php if(!empty($record['review_image_url'])): ?><p><?php viewSafeLink($record['review_image_url'],'View review image'); ?></p><?php endif; ?></div><div><h3>Moderation decision</h3><p class="section-note">Assess the content fairly. A low rating alone is not a reason to hide a review.</p><form method="post" action="<?= e(url('reviews')) ?>" class="stack-form"><?= viewFields('review_moderate',$recordId,$version) ?><div><label for="review-decision">Decision</label><select id="review-decision" name="decision" required><option value="">Choose a decision</option><option value="hide">Hide review</option><option value="dismiss">Keep / restore review and dismiss flag</option></select></div><?php viewReason('review-reason','Moderation reason'); ?><button class="button button-primary">Save moderation decision</button></form></div></div>
<?php elseif($page==='disputes'): ?>
    <div class="detail-grid"><div><h3><?= e($record['subject']) ?></h3><p><?= badge($record['status']) ?></p><p class="preserve-text"><?= e($record['description']) ?></p><dl class="detail-list"><?php viewPair('Opened',localDate($record['created_at']));viewPair('Last updated',localDate($record['updated_at']));if($record['resolved_at']) viewPair('Resolved',localDate($record['resolved_at'])); ?></dl><a class="text-link" href="<?= e(url('bookings',['id'=>$record['booking_id']])) ?>">View related booking →</a><?php if($record['resolution']): ?><div class="info-card"><strong>Recorded resolution</strong><p class="preserve-text"><?= e($record['resolution']) ?></p></div><?php endif; ?></div><div><h3>Review & resolve</h3><?php if(in_array($record['status'],['Open','Under Review'],true)): ?><form class="stack-form" method="post" action="<?= e(url('disputes')) ?>"><?= viewFields('dispute_resolve',$recordId,$version) ?><div><label for="dispute-status">Decision</label><select id="dispute-status" name="status" required><option value="">Choose a decision</option><?php if($record['status']==='Open'): ?><option value="Under Review">Begin review</option><?php endif; ?><option value="Resolved">Resolve dispute</option><option value="Dismissed">Dismiss dispute</option></select></div><?php viewReason('resolution-reason','Review notes / resolution'); ?><p class="field-note">Resolving a dispute does not issue a refund. Refund requests are handled through the related booking.</p><button class="button button-primary">Save decision</button></form><?php else: ?><div class="info-card">This dispute has been closed. Its decision remains available in the audit trail.</div><?php endif; ?></div></div>
<?php endif; ?>
</div></section>
